use serde_json::{json,Value};use sha2::{Sha256,Digest};
use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},process::{Command,Stdio},io::{BufRead,BufReader},fmt::Write};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups175";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn checkpins(p:&BTreeMap<String,String>){for(f,h)in p {assert_eq!(hash(f),*h,"pin {f}");}}
fn prepare(){assert_eq!(read(r("native/result.json"))["status"],"complete");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("pins-before.json"))).unwrap();checkpins(&pins);
let tests=fs::read_to_string(r("native/run-tests/stdout.log")).unwrap();assert!(tests.contains("5 passed; 0 failed"));
for p in ["perf","codegen"]{fs::create_dir_all(r(p)).unwrap();}for p in ["ctl","ack"]{if !r(p).exists(){assert!(Command::new("mkfifo").arg(r(p)).status().unwrap().success());}}
let nm=Command::new("nm").args(["-S","--size-sort","--defined-only"]).arg(r("probe")).output().unwrap();assert!(nm.status.success());let syms=String::from_utf8(nm.stdout).unwrap();fs::write(r("codegen/symbols.txt"),&syms).unwrap();
let mut linked=vec![];for line in syms.lines().filter(|l|l.contains("_5probe5build")){let sym=line.split_whitespace().last().unwrap();let d=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={sym}")).arg(r("probe")).output().unwrap();assert!(d.status.success());let f=format!("codegen/{}.asm",linked.len());fs::write(r(&f),d.stdout).unwrap();linked.push(json!({"symbol":sym,"row":line,"file":f}));}
assert_eq!(linked.len(),1);save(r("codegen.json"),&json!(linked));
let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");let env=manifest["environment"].clone();
let mut steps=vec![json!({"kind":"command","name":"latency","argv":[r("probe"),"latency",r("cases.json")],"environment":env,"timeout_seconds":1800})];
for (variant,mode)in[("original","0"),("candidate","1")]{let mut e=env.clone();e["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));e["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));let mut args=vec!["sudo".to_string(),"-n".into(),"env".into()];for(k,v)in e.as_object().unwrap(){args.push(format!("{k}={}",v.as_str().unwrap()));}args.extend(["perf".into(),"record".into(),"--no-buildid-cache".into(),"-e".into(),"cycles:u".into(),"-F".into(),"199".into(),"-m".into(),"512".into(),"-o".into(),r(format!("perf/{variant}.data")).display().to_string(),"--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into(),r("probe").display().to_string(),"profile".into(),r("cases.json").display().to_string(),mode.into()]);steps.push(json!({"kind":"command","name":format!("profile-{variant}"),"argv":args,"environment":env,"timeout_seconds":1800}));}
let uid=String::from_utf8(Command::new("id").arg("-u").output().unwrap().stdout).unwrap();let gid=String::from_utf8(Command::new("id").arg("-g").output().unwrap().stdout).unwrap();
for variant in ["original","candidate"]{steps.push(json!({"kind":"command","name":format!("own-{variant}"),"argv":["sudo","-n","chown",format!("{}:{}",uid.trim(),gid.trim()),r(format!("perf/{variant}.data"))],"timeout_seconds":60}));}
for variant in ["original","candidate"]{let data=r(format!("perf/{variant}.data"));steps.push(json!({"kind":"command","name":format!("decode-{variant}"),"argv":["perf","script","--header","--show-lost-events","-i",data,"-F","pid,tid,period,ip,sym"],"timeout_seconds":180}));steps.push(json!({"kind":"command","name":format!("events-{variant}"),"argv":["perf","evlist","-v","-i",data],"timeout_seconds":60}));steps.push(json!({"kind":"command","name":format!("loss-{variant}"),"argv":[r("runner"),"loss",data],"timeout_seconds":180}));}
for f in ["runner.rs","runner","native/result.json","native/run-tests/stdout.log","probe","probe-tests","codegen.json","codegen/symbols.txt"]{pins.insert(r(f).display().to_string(),hash(r(f)));}for l in linked{let f=r(l["file"].as_str().unwrap());pins.insert(f.display().to_string(),hash(f));}
save(r("pins.json"),&json!(pins));save(r("run-plan.json"),&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));println!("Prepared 11 steps, 1116 latency cells/8928 constructors, two separate gated profiles; all helper compilation complete");}
fn loss(p:&str){let mut c=Command::new("perf").args(["script","-D","-i",p]).stdout(Stdio::piped()).spawn().unwrap();let mut lost=vec![];let mut lines=0;for line in BufReader::new(c.stdout.take().unwrap()).lines(){let line=line.unwrap();lines+=1;if line.contains("PERF_RECORD_LOST"){lost.push(line);}}assert!(c.wait().unwrap().success());println!("{}",json!({"lines":lines,"lost":lost,"zero_lost":lost.is_empty()}));}
fn median(xs:&[f64])->f64{let mut s=xs.to_vec();s.sort_by(f64::total_cmp);s[s.len()/2]}
fn rank(xs:&[f64])->Value{assert_eq!(xs.len(),31);let mut s=xs.to_vec();s.sort_by(f64::total_cmp);json!({"median":s[15],"low":s[9],"high":s[21],"wins":xs.iter().filter(|&&v|v<1.).count(),"ratios":xs,"nominal_coverage":0.9705506265163422})}
fn finish(){assert_eq!(read(r("runs/result.json"))["status"],"complete");let pins:BTreeMap<String,String>=serde_json::from_value(read(r("pins.json"))).unwrap();checkpins(&pins);
let log=fs::read_to_string(r("runs/latency/stdout.log")).unwrap();let mut inputs=vec![];let mut rows=BTreeMap::<(String,bool),Vec<Value>>::new();let mut complete=None;
for line in log.lines(){if let Some(v)=line.strip_prefix("INPUT "){inputs.push(serde_json::from_str::<Value>(v).unwrap());}if let Some(v)=line.strip_prefix("ROW "){let v:Value=serde_json::from_str(v).unwrap();assert_eq!(v["all_outputs_oracle_checked"],true);assert_eq!(v["calls"],8);rows.entry((v["context"].as_str().unwrap().into(),v["on"].as_bool().unwrap())).or_default().push(v);}if let Some(v)=line.strip_prefix("COMPLETE "){complete=Some(serde_json::from_str::<Value>(v).unwrap());}}
assert_eq!(inputs.len(),18);assert_eq!(rows.len(),36);let complete=complete.unwrap();assert_eq!(complete["timed_builders"],8928);
let mut pairs=BTreeMap::new();let mut cells=BTreeMap::new();let mut checks=BTreeMap::new();
for i in &inputs{let name=i["name"].as_str().unwrap();let off=&rows[&(name.into(),false)];let on=&rows[&(name.into(),true)];assert_eq!(off.len(),31);assert_eq!(on.len(),31);for b in 0..31{assert_eq!(off[b]["block"],b);assert_eq!(on[b]["block"],b);}
for(flag,label)in[(false,"original"),(true,"candidate")]{cells.insert(format!("{name}/{label}"),json!({"median_ms":median(&rows[&(name.into(),flag)].iter().map(|v|v["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>()),"blocks":rows[&(name.into(),flag)]}));}
let ratios=(0..31).map(|b|on[b]["mean_ms"].as_f64().unwrap()/off[b]["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let p=rank(&ratios);checks.insert(format!("{name}/nonregression"),p["high"].as_f64().unwrap()<=1.03);if name=="1x2/A"||name=="1x2/B"{checks.insert(format!("{name}/gain"),p["high"].as_f64().unwrap()<1.&&p["wins"].as_u64().unwrap()>=21);}pairs.insert(name.to_string(),p);}
let aggregate=rank(&(0..31).map(|b|(pairs.values().map(|p|p["ratios"][b].as_f64().unwrap().ln()).sum::<f64>()/18.).exp()).collect::<Vec<_>>());checks.insert("all18/gain".into(),aggregate["high"].as_f64().unwrap()<1.&&aggregate["wins"].as_u64().unwrap()>=21);
let mut profiles=BTreeMap::new();for variant in ["original","candidate"]{assert_eq!(read(r(format!("runs/loss-{variant}/stdout.log")))["zero_lost"],true);let events=fs::read_to_string(r(format!("runs/events-{variant}/stdout.log"))).unwrap();assert!(events.contains("cycles:u")&&events.contains("199"));let mut symbols=BTreeMap::<String,u64>::new();let mut pids=BTreeSet::new();let mut samples=0;
for line in fs::read_to_string(r(format!("runs/decode-{variant}/stdout.log"))).unwrap().lines().filter(|l|!l.trim().is_empty()&&!l.trim().starts_with('#')){let f=line.split_whitespace().collect::<Vec<_>>();let(pid,_)=f[0].split_once('/').unwrap();pids.insert(pid.to_string());*symbols.entry(f[3..].join(" ")).or_default()+=f[1].parse::<u64>().unwrap();samples+=1;}assert_eq!(pids.len(),1);assert!(samples>0);profiles.insert(variant,json!({"samples":samples,"PIDs":pids,"zero_lost":true,"symbol_periods":symbols,"raw_sha256":hash(r(format!("perf/{variant}.data")))}));}
let failed=checks.iter().filter(|(_,p)|!**p).map(|(k,_)|k.clone()).collect::<Vec<_>>();let data=json!({"component_gate":failed.is_empty(),"checks":checks,"failed_checks":failed,"aggregate":aggregate,"pairs":pairs,"cells":cells,"inputs":inputs,"profiles":profiles,"complete":complete,"native_tests":5,"SDK_requests":0,"new_proofs":0,"ledger":20881,"production_changed":false,"adopted":false,"source_pins_closed":pins.len(),"scope":"CPU2 single-thread builder on real A/B scalar inputs; no new full-proof latency"});save(r("analysis.json"),&data);
println!("Component gate {}; failed {}",data["component_gate"],data["failed_checks"]);for(name,p)in pairs{println!("{name}: {} [{},{}] wins{}",p["median"],p["low"],p["high"],p["wins"]);}println!("aggregate {}",aggregate);
}
fn main(){let args:Vec<_>=std::env::args().collect();match args[1].as_str(){"prepare"=>prepare(),"loss"=>loss(&args[2]),"finish"=>finish(),_=>panic!()}}
